from __future__ import annotations

import json
from pathlib import Path

import pytest

from src.idempotency import (
    IdempotencyStore,
    apply_batch,
    comment_key,
    create_key,
    effect_key,
    normalize,
)
from src.reconcile import reconcile, reconcile_decisions

# The reference vectors. Those holding U+001C-U+001F, U+0085 or U+FEFF, on which Python's
# whitespace and JavaScript's differ, were generated by running the n8n Idempotency check
# node's own code, and tests/test_n8n_parity.py checks every vector against it again.
VECTORS = json.loads(
    (Path(__file__).resolve().parent / "idempotency_vectors.json").read_text(encoding="utf-8")
)


@pytest.mark.parametrize("case", VECTORS["normalize"])
def test_normalize_vectors(case):
    assert normalize(case["in"]) == case["out"]


def test_normalize_handles_none():
    assert normalize(None) == ""


@pytest.mark.parametrize("case", VECTORS["effect_key"])
def test_effect_key_matches_pinned_vectors(case):
    assert effect_key(case["kind"], case["target"], case["content"]) == case["key"]


def test_new_and_update_keys_differ_for_same_text():
    assert effect_key("NEW", "", "ship it") != effect_key("UPDATE", "t1", "ship it")


def test_update_key_depends_on_target():
    assert effect_key("UPDATE", "t1", "x") != effect_key("UPDATE", "t2", "x")


def test_a_null_name_or_description_keys_like_an_absent_one():
    # A model that answers null means there is nothing there. The n8n Idempotency check
    # reads (j.name || '') and (j.description || ''), so the key does too: str(None) would
    # hash the word "None" and give one effect two keys in the store the app and n8n
    # share. The node itself is run in tests/test_n8n_parity.py; this holds without node.
    body, name = "alert on CDN errors", "[Dev] Null description"
    assert create_key({"name": None, "description": body}) == create_key({"description": body})
    assert create_key({"name": name, "description": None}) == create_key({"name": name})


# --- one name and one body per point ---

# A point in each shape it comes in: a task, an action item as extraction writes it, a
# point that carries its body as `detail` (an eval entry), and a task whose name is null.
POINTS = {
    "task": {"name": "[Dev] New alerting", "description": "alert on CDN errors"},
    "action item": {"what": "Alert on CDN errors", "context": "the CDN failed twice this week"},
    "eval entry": {"name": "Alert on CDN errors", "detail": "the CDN failed twice this week"},
    "null name": {"name": None, "description": "alert on CDN errors"},
}


@pytest.mark.parametrize("shape", list(POINTS))
def test_a_point_keys_alike_before_and_after_reconcile(shape):
    # reconcile() hands a point on as `name` and `detail`, and the plan applies that
    # record; the key must not care which of the two it is given. That holds only if
    # reconcile() and the key read a point's name and body by one definition.
    point = POINTS[shape]
    record = reconcile([dict(point)], [])[0]  # an empty board asks no model
    assert create_key(record) == create_key(point)
    target = {"target_id": "86abc"}
    assert comment_key({**record, **target}) == comment_key({**point, **target})


def test_a_meeting_decision_is_keyed_on_its_sentence_whatever_else_it_carries(monkeypatch):
    # A meeting decision is one sentence, and that sentence is its body: a rule, not a
    # fallback. Keyed through a fallback, a field given to meeting decisions later -- a
    # context, a description -- would become the body, re-key every comment already
    # applied for one, and the next run would post it again.
    monkeypatch.setattr("src.reconcile.ask", lambda system, prompt, max_tokens=400: (
        "DECISION: UPDATE\nTASK_ID: 86abc\nCONFIDENCE: 0.9\nREASON: same release"))
    board = [{"id": "86abc", "name": "[Release] Cut the August release"}]
    meeting_decision = {"what": "Ship Wednesday, cut payments", "affects": "the release",
                        "kind": "scope_change"}
    decided = reconcile_decisions([meeting_decision], board)[0]
    applied = effect_key("UPDATE", "86abc", "Ship Wednesday, cut payments")
    assert comment_key(decided) == applied
    for field in ("detail", "description", "context"):
        assert comment_key({**decided, field: "a field meeting decisions lack today"}) == applied


def test_store_empty_is_not_duplicate(tmp_path):
    store = IdempotencyStore(tmp_path / "s.jsonl")
    assert store.is_duplicate("abc") is False


def test_commit_makes_key_duplicate_and_persists(tmp_path):
    p = tmp_path / "s.jsonl"
    store = IdempotencyStore(p)
    store.commit("abc", {"kind": "NEW", "preview": "x"})
    assert store.is_duplicate("abc") is True
    # a fresh instance reads the committed key back from disk
    assert IdempotencyStore(p).is_duplicate("abc") is True


def test_mark_seen_catches_second_in_same_batch(tmp_path):
    store = IdempotencyStore(tmp_path / "s.jsonl")
    assert store.is_duplicate("k") is False
    store.mark_seen("k")            # first effect, not yet applied/committed
    assert store.is_duplicate("k") is True  # second identical effect in the batch


def test_malformed_line_is_ignored(tmp_path):
    p = tmp_path / "s.jsonl"
    p.write_text('{"key": "good"}\nnot json\n{"nokey": 1}\n', encoding="utf-8")
    store = IdempotencyStore(p)
    assert store.is_duplicate("good") is True


def test_second_run_applies_nothing(tmp_path):
    effects = [("UPDATE", "t1", "saved cards unblocked"),
               ("NEW", "", "investigate ios funnel"),
               ("UPDATE", "t2", "crash fix in review")]
    store = IdempotencyStore(tmp_path / "s.jsonl")
    applied1, skipped1 = apply_batch(effects, store)
    applied2, skipped2 = apply_batch(effects, store)
    assert (applied1, skipped1) == (3, 0)
    assert (applied2, skipped2) == (0, 3)


def test_duplicate_within_one_batch_applied_once(tmp_path):
    effects = [("UPDATE", "t1", "same"), ("UPDATE", "t1", "same")]
    store = IdempotencyStore(tmp_path / "s.jsonl")
    applied, skipped = apply_batch(effects, store)
    assert (applied, skipped) == (1, 1)
